import { compileToDirectWasm } from './wasm-direct.js?v=868f0784ca7f3972';

export const PATCH_C99_VERSION = '0.1';

/**
 * Lower the currently supported direct numeric Console subset to portable C99.
 *
 * The direct-Wasm compiler is used as the conservative support-boundary
 * validator first. The C source is then generated independently from the
 * normalized Change IR so unsupported Patch constructs cannot silently fall
 * back to the interpreter.
 */
export function compileToC99(source, options = {}) {
  const validated = compileToDirectWasm(source, { ...options, kind: options.kind ?? 'console' });
  const compiled = validated.compiled;
  const instructions = compiled.ir.instructions ?? [];
  const stateNames = instructions.filter(item => item.code === 'CREATE').map(item => item.name);
  const stateIds = new Map(stateNames.map((name, index) => [name, index]));
  const recipes = instructions.filter(item => item.code === 'MAKE');
  const recipeNames = new Set(recipes.map(item => item.name));
  const counters = { temp: 0, loop: 0 };

  const globals = stateNames.map(name => `static double ${stateName(name)} = 0.0;`);
  const prototypes = recipes.map(recipe => `static void ${recipeName(recipe.name)}(${parameterList(recipe)});`);
  const definitions = recipes.map(recipe => lowerRecipe(recipe, stateIds, recipeNames, counters));

  const mainContext = {
    stateIds,
    recipeNames,
    defined: new Set(),
    locals: new Map(),
    counters,
    allowCreate: true,
    allowDefinitions: true
  };
  const mainBody = lowerBlock(instructions, mainContext, 1);

  const cSource = [
    '/* Generated by Patch portable C99 backend. */',
    `/* Backend version: ${PATCH_C99_VERSION}; Patch IR: ${compiled.ir.version}. */`,
    '#include <math.h>',
    '#include <stdio.h>',
    '#include <stdlib.h>',
    '',
    'static void patch_show_number(double value) {',
    '  if (isnan(value)) { puts("NaN"); return; }',
    '  if (isinf(value)) { puts(signbit(value) ? "-Infinity" : "Infinity"); return; }',
    '  if (value == 0.0) { puts("0"); return; }',
    '  printf("%.15g\\n", value);',
    '}',
    '',
    'static void patch_change_number(int target_id, double before, double after) {',
    '  (void)target_id;',
    '  (void)before;',
    '  (void)after;',
    '#ifdef PATCH_TRACE',
    '  fprintf(stderr, "patch-change %d %.17g %.17g\\n", target_id, before, after);',
    '#endif',
    '}',
    '',
    'static void patch_range_error(const char *recipe, const char *parameter, double value, double minimum, double maximum) {',
    '  fprintf(stderr, "Patch range guard failed: %s.%s = %.17g, expected %.17g..%.17g\\n", recipe, parameter, value, minimum, maximum);',
    '  exit(2);',
    '}',
    '',
    ...globals,
    globals.length ? '' : null,
    ...prototypes,
    prototypes.length ? '' : null,
    ...definitions.flatMap((definition, index) => index === definitions.length - 1 ? [definition] : [definition, '']),
    definitions.length ? '' : null,
    'int main(void) {',
    ...mainBody,
    '  return 0;',
    '}',
    ''
  ].filter(line => line !== null).join('\n');

  return {
    source: cSource,
    metadata: {
      format: 'patch-c99',
      version: PATCH_C99_VERSION,
      project: compiled.project,
      irVersion: compiled.ir.version,
      numericModel: 'C99 double / finite Patch numeric subset',
      stateTargets: stateNames,
      supported: [
        'top-level numeric create',
        'numeric change set/add/remove/clear',
        'numeric show',
        'numeric + - * /',
        'if/else with direct-subset conditions',
        'literal repeat with Patch count',
        'non-recursive acyclic numeric recipes',
        'ranged numeric recipe guards'
      ]
    },
    compiled
  };
}

function lowerRecipe(recipe, stateIds, recipeNames, counters) {
  const locals = new Map((recipe.params ?? []).map(name => [name, parameterName(name)]));
  const context = {
    stateIds,
    recipeNames,
    defined: new Set(stateIds.keys()),
    locals,
    counters,
    allowCreate: false,
    allowDefinitions: false
  };
  const lines = [`static void ${recipeName(recipe.name)}(${parameterList(recipe)}) {`];
  for (const [name, range] of Object.entries(recipe.paramRanges ?? {})) {
    const local = parameterName(name);
    lines.push(`  if (${local} < ${cNumber(range.min)} || ${local} > ${cNumber(range.max)}) {`);
    lines.push(`    patch_range_error(${cString(recipe.name)}, ${cString(name)}, ${local}, ${cNumber(range.min)}, ${cNumber(range.max)});`);
    lines.push('  }');
  }
  lines.push(...lowerBlock(recipe.body ?? [], context, 1));
  lines.push('}');
  return lines.join('\n');
}

function lowerBlock(block, context, depth) {
  const lines = [];
  for (const instruction of block ?? []) lines.push(...lowerInstruction(instruction, context, depth));
  return lines;
}

function lowerInstruction(instruction, context, depth) {
  const indent = '  '.repeat(depth);
  switch (instruction.code) {
    case 'ALLOW_CHANGES':
      if (!context.allowDefinitions) throw new Error('C99 backend: allow declarations must remain top level.');
      return [];

    case 'MAKE':
      if (!context.allowDefinitions) throw new Error(`C99 backend: nested recipe '${instruction.name}' is unsupported.`);
      return [];

    case 'CREATE': {
      if (!context.allowCreate) throw new Error(`C99 backend: create '${instruction.name}' is only supported at top level.`);
      const state = requireState(instruction.name, context);
      const expression = cExpression(instruction.expr, context);
      context.defined.add(instruction.name);
      return [`${indent}${state} = ${expression};`];
    }

    case 'CHANGE': {
      const id = requireDefinedState(instruction.target, context);
      const state = stateName(instruction.target);
      const before = `patch_before_${context.counters.temp++}`;
      const lines = [`${indent}{`, `${indent}  double ${before} = ${state};`];
      for (const operation of instruction.operations ?? []) {
        if (operation.field) throw new Error(`C99 backend: field change '${instruction.target}.${operation.field}' is outside the numeric subset.`);
        if (operation.op === 'clear') {
          lines.push(`${indent}  ${state} = 0.0;`);
          continue;
        }
        const expression = cExpression(operation.expr, context);
        if (operation.op === 'set') lines.push(`${indent}  ${state} = ${expression};`);
        else if (operation.op === 'add') lines.push(`${indent}  ${state} += ${expression};`);
        else if (operation.op === 'remove') lines.push(`${indent}  ${state} -= ${expression};`);
        else throw new Error(`C99 backend: unsupported change operation '${operation.op}'.`);
      }
      lines.push(`${indent}  patch_change_number(${id}, ${before}, ${state});`);
      lines.push(`${indent}}`);
      return lines;
    }

    case 'SHOW':
      return [`${indent}patch_show_number(${cExpression(instruction.expr, context)});`];

    case 'IF': {
      const lines = [`${indent}if (${cExpression(instruction.expr, context)}) {`];
      lines.push(...lowerBlock(instruction.then ?? [], childContext(context), depth + 1));
      if ((instruction.else ?? []).length) {
        lines.push(`${indent}} else {`);
        lines.push(...lowerBlock(instruction.else ?? [], childContext(context), depth + 1));
      }
      lines.push(`${indent}}`);
      return lines;
    }

    case 'REPEAT': {
      const count = literalRepeatCount(instruction.expr);
      const loop = `patch_count_${context.counters.loop++}`;
      const child = childContext(context, new Map(context.locals));
      child.locals.set('count', loop);
      const lines = [`${indent}for (int ${loop} = 1; ${loop} <= ${count}; ++${loop}) {`];
      lines.push(...lowerBlock(instruction.body ?? [], child, depth + 1));
      lines.push(`${indent}}`);
      return lines;
    }

    case 'DO': {
      if (!context.recipeNames.has(instruction.name)) throw new Error(`C99 backend: unknown recipe '${instruction.name}'.`);
      const args = (instruction.args ?? []).map(arg => cExpression(arg, context)).join(', ');
      return [`${indent}${recipeName(instruction.name)}(${args});`];
    }

    case 'RETURN':
      throw new Error('C99 backend: return-valued recipes are outside the portable subset.');

    default:
      throw new Error(`C99 backend: '${instruction.code}' is outside the portable numeric subset.`);
  }
}

function childContext(context, locals = context.locals) {
  return {
    ...context,
    locals,
    allowCreate: false,
    allowDefinitions: false
  };
}

function cExpression(source, context) {
  const tokens = tokenize(String(source ?? ''));
  return tokens.map(token => {
    if (token.type === 'number') return cNumericToken(token.text);
    if (token.type !== 'word') return token.text;
    if (token.text === 'true') return '1';
    if (token.text === 'false') return '0';
    if (token.text === 'and') return '&&';
    if (token.text === 'or') return '||';
    if (token.text === 'not') return '!';
    if (context.locals.has(token.text)) return context.locals.get(token.text);
    requireDefinedState(token.text, context);
    return stateName(token.text);
  }).join(' ');
}

function tokenize(source) {
  const text = source.trim();
  if (!text) throw new Error('C99 backend: missing expression.');
  const out = [];
  const pattern = /\s*(?:(\d+(?:\.\d+)?)|([A-Za-z_][A-Za-z0-9_]*)|(==|!=|<=|>=|\+|-|\*|\/|%|<|>|\(|\)))/gy;
  let position = 0;
  while (position < text.length) {
    pattern.lastIndex = position;
    const match = pattern.exec(text);
    if (!match) throw new Error(`C99 backend: unsupported expression near '${text.slice(position)}'.`);
    position = pattern.lastIndex;
    if (match[1] !== undefined) out.push({ type: 'number', text: match[1] });
    else if (match[2] !== undefined) out.push({ type: 'word', text: match[2] });
    else out.push({ type: 'operator', text: match[3] });
  }
  return out;
}

function collectStateName(name) {
  return `patch_state_${safeIdentifier(name)}`;
}

function stateName(name) {
  return collectStateName(name);
}

function recipeName(name) {
  return `patch_recipe_${safeIdentifier(name)}`;
}

function parameterName(name) {
  return `patch_arg_${safeIdentifier(name)}`;
}

function parameterList(recipe) {
  const params = recipe.params ?? [];
  if (!params.length) return 'void';
  return params.map(name => `double ${parameterName(name)}`).join(', ');
}

function requireState(name, context) {
  if (!context.stateIds.has(name)) throw new Error(`C99 backend: unknown persistent numeric binding '${name}'.`);
  return stateName(name);
}

function requireDefinedState(name, context) {
  const state = requireState(name, context);
  if (!context.defined.has(name)) throw new Error(`C99 backend: '${name}' is referenced before its create.`);
  return context.stateIds.get(name) ?? state;
}

function literalRepeatCount(source) {
  const text = String(source ?? '').trim();
  if (!/^\d+$/.test(text)) throw new Error(`C99 backend: repeat count '${text || '?'}' must be a literal whole number.`);
  const value = Number(text);
  if (!Number.isSafeInteger(value) || value < 0 || value > 100000) throw new Error('C99 backend: repeat count must be from 0 to 100000.');
  return value;
}

function cNumericToken(text) {
  return text.includes('.') ? text : `${text}.0`;
}

function cNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) throw new Error(`C99 backend: non-finite compile-time number '${value}' is unsupported.`);
  const text = String(number);
  if (/[.eE]/.test(text)) return text;
  return `${text}.0`;
}

function cString(value) {
  return JSON.stringify(String(value)).replace(/\\u2028|\\u2029/g, '');
}

function safeIdentifier(name) {
  const text = String(name);
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(text)) throw new Error(`C99 backend: '${text}' is not a portable identifier.`);
  return text;
}
